export default function FeedbackCard({
  suggestion,
  onAccept,
  onReject,
}) {
  return (
    <div className="feedback-card">
      <div className="feedback-card-header">
        ✨ SUGGESTED ACTION — NEEDS YOUR APPROVAL
      </div>

      <div className="feedback-card-title">
        {suggestion.title}
      </div>

      <div className="feedback-card-row">
        <strong>Method:</strong> {suggestion.method}
      </div>

      <div className="feedback-card-row">
        <strong>Target:</strong> {suggestion.target}
      </div>

      <div className="feedback-card-row">
        <strong>Why:</strong> {suggestion.why}
      </div>

      <div className="feedback-actions">
        <button onClick={onAccept}>
          ✓ Accept
        </button>

        <button onClick={onReject}>
          ✕ Reject
        </button>
      </div>
    </div>
  );
}
